    vec3<float> sampleBilinear(const ImageAccessor& image, float h, float w)
    {
      h = clamp(h, 0.f, float(image.H - 1));
      w = clamp(w, 0.f, float(image.W - 1));

      const int h0 = int(h);
      const int w0 = int(w);
      const int h1 = min(h0 + 1, image.H - 1);
      const int w1 = min(w0 + 1, image.W - 1);
