      const vec3<float> v01 = image.get3(h0, w1);
      const vec3<float> v10 = image.get3(h1, w0);
      const vec3<float> v11 = image.get3(h1, w1);

      return (v00 * (1.f - fw) + v01 * fw) * (1.f - fh) +
